import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { CreditoProductoFinancieroDocumento } from '../models/creditos.productos.financieros.documento';
import { firstValueFrom } from 'rxjs';

@Injectable({
  providedIn: 'any'
})
export class CreditoProductoFinancieroDocumentoService extends SuperService<CreditoProductoFinancieroDocumento> {
  protected override model: string ="creditos_documentos";
  protected override columns: (keyof CreditoProductoFinancieroDocumento)[] = [
    "credito_id",
    "productos_financieros_documento_id",
    "productos_financieros_documentos",
    "url",
    "usuario_id",
  ];

  constructor(injector: Injector){
    super(injector)
  }

  verificarDocumento(id:number){
    const url='api/access/credito/documento/aprobar'
    return firstValueFrom(this.api.post(url,{id}))
  }
}
